              <hlm-select-value placeholder="All classes" />
            </hlm-select-trigger>
            <hlm-select-content *hlmSelectPortal>
              @for (option of vm.classOptions; track option) {
                <hlm-select-item [value]="option">{{ option }}</hlm-select-item>
              }
            </hlm-select-content>
          </hlm-select>
        </hlm-field>

        <a hlmBtn class="ms-auto" routerLink="/recruit">
          <ng-icon name="lucideUserPlus" />
          Recruit
        </a>
      </div>

      @if (vm.visibleCount() === 0) {
        <p class="text-sm text-muted-foreground">No heroes match these filters.</p>
      }

      <div class="hidden sm:block">
        <div hlmTableContainer>
          <table hlmTable aria-label="Hero roster">
            <thead hlmTHead>
              <tr hlmTr>
                <th hlmTh>Hero</th>
                <th hlmTh>Class</th>
                <th hlmTh>Power</th>
                <th hlmTh>Status</th>
                <th hlmTh class="hidden md:table-cell">Clearance</th>
                <th hlmTh><span class="sr-only">Actions</span></th>
              </tr>
            </thead>
            <tbody hlmTBody>
              @for (row of vm.rows(); track row.hero.id) {
                <tr hlmTr>
                  <td hlmTd>
                    <div class="flex items-center gap-3">
                      <hlm-avatar aria-hidden="true">
                        <span hlmAvatarFallback>{{ row.initials }}</span>
                      </hlm-avatar>
                      <div class="flex min-w-0 flex-col">
                        <a class="font-medium underline-offset-4 hover:underline" [routerLink]="['/detail', row.hero.id]">{{ row.hero.name }}</a>
                        <span class="text-xs text-muted-foreground">{{ row.hero.id }}</span>
                      </div>
                    </div>
                  </td>
                  <td hlmTd><span hlmBadge variant="secondary">{{ row.hero.powerClass }}</span></td>
                  <td hlmTd>{{ row.hero.power }}</td>
                  <td hlmTd><span hlmBadge [variant]="row.statusVariant">{{ row.hero.status }}</span></td>
                  <td hlmTd class="hidden md:table-cell">{{ row.hero.clearance }}</td>
                  <td hlmTd>
                    <a
                      hlmBtn
                      variant="ghost"
                      size="icon"
                      hlmTooltip="Edit hero"
                      [attr.aria-label]="'Edit ' + row.hero.name"
                      [routerLink]="['/detail', row.hero.id]"
                    >
                      <ng-icon name="lucidePencil" />
                    </a>
                  </td>
                </tr>
              }
            </tbody>
          </table>
        </div>
      </div>

      <div class="flex flex-col gap-3 sm:hidden">
        @for (row of vm.rows(); track row.hero.id) {
          <app-roster-hero-card [hero]="row.hero" />
        }
      </div>

      <footer class="flex flex-wrap items-center justify-between gap-2 text-sm text-muted-foreground">
        <p>{{ vm.visibleCount() }} of {{ vm.totalCount() }} heroes</p>
        <p>Sorted by power</p>
      </footer>
    </section>
  `,
})
export class Heroes {
  protected readonly vm = inject(HeroesViewModel);
}
